import { Metadata } from "next";
import Link from "next/link";
import { Suspense } from "react";
import LiveClient from "./LiveClient";

const CANONICAL = "https://www.trayago.in/live";

// 1. Technical SEO Metadata for Live Portal
export const metadata: Metadata = {
  title: "Live Train Running Status & Tracking | Trayago",
  description:
    "Check live train running status on Trayago. Enter a train number to see current running information, last reported station, delay, and estimated arrival and departure times across Indian Railways.",
  alternates: {
    canonical: CANONICAL,
  },
  keywords:
    "live train running status, live train status, train running status, live train tracking, train location, train delay status, train ETA, train tracker India, railway live status",
  robots: {
    index: true,
    follow: true,
  },
  // PHASE_SEO-004: social card metadata added to match the verified pattern on
  // /tracker. Live status is a frequently shared surface; without these tags it
  // rendered a bare link preview. Title/description/canonical intentionally unchanged.
  openGraph: {
    type: "website",
    title: "Live Train Running Status & Tracking | Trayago",
    description:
      "Check live train running status on Trayago. Enter a train number to see current running information, last reported station, delay, and estimated arrival times.",
    url: CANONICAL,
    siteName: "Trayago",
  },
  twitter: {
    card: "summary_large_image",
    title: "Live Train Running Status & Tracking",
    description:
      "Check live train running status, last reported station, delay, and estimated arrival times across Indian Railways.",
  },
};

// Static list of widely searched trains — provides crawlable entry points into /live/[trainNo].
// Display/link data only; no API calls and no coupling to LiveClient state.
const POPULAR_TRAINS: { number: string; name: string }[] = [
  { number: "12002", name: "NDLS–BPL Shatabdi" },
  { number: "12952", name: "MMCT–NDLS Rajdhani" },
  { number: "12301", name: "HWH–NDLS Rajdhani" },
  { number: "12626", name: "Kerala Express" },
  { number: "12260", name: "HWH–NDLS Duronto" },
  { number: "12004", name: "LJN–NDLS Shatabdi" },
];

// 2. Single source of truth for FAQ — rendered visibly AND as FAQPage JSON-LD
const LIVE_FAQS: { q: string; a: string }[] = [
  {
    q: "What is live train running status?",
    a: "Live train running status is the current running information for a train on a given day: the station it was last reported at, whether it is on time or delayed, and the expected arrival and departure times at the stations still ahead on its route.",
  },
  {
    q: "How can I check my train's live running status on Trayago?",
    a: "Enter the train number in the field at the top of this page and select Track Train. Trayago loads the current running information for that train, including its progress along the route, delay against the scheduled timetable, and station-wise timings. Selecting a different journey date lets you look at the relevant run of the train.",
  },
  {
    q: "Can I see where my train is right now?",
    a: "Trayago shows the train's position along its route based on the latest reported running information, so you can see which stations it has passed and which are still ahead. This reflects the most recent update available rather than continuous second-by-second positioning.",
  },
  {
    q: "How are train delays shown?",
    a: "Delay is shown as the difference in minutes between the scheduled timetable and the latest reported running information. A train reported at or ahead of schedule is marked as on time, and a train behind schedule shows how many minutes late it is currently running.",
  },
  {
    q: "What does ETA mean in live train status?",
    a: "ETA is the estimated time of arrival at a station. Trayago derives it by applying the current delay to the scheduled arrival time for each upcoming station. Because delays can grow or shrink while a train is running, an ETA is an estimate and can shift during the journey.",
  },
  {
    q: "How often does live train running status update?",
    a: "Trayago refreshes the running information for a tracked train automatically about every 30 seconds while the page is open, and applies live updates as they are received. The underlying railway data itself changes only when the train reports at a location, so the displayed position may stay the same between reports.",
  },
  {
    q: "Can train timings change after I check the status?",
    a: "Yes. Running information, delay, platform assignment, and estimated timings can all change while a train is en route due to traffic, signalling, or operational decisions. Checking again closer to the arrival time gives you the most current picture.",
  },
  {
    q: "Is live train information always accurate?",
    a: "It is as accurate as the latest available railway running data for that train, which means it can lag behind reality between station reports and can occasionally be incomplete for special or newly introduced trains. For platform numbers and last-minute changes, confirm with official station announcements.",
  },
  {
    q: "What is the 'Inside' vs 'Outside' tracking toggle?",
    a: "Outside mode uses railway running information to show where the train has been reported. Inside mode is for when you are travelling on the train and uses your own device's GPS to estimate speed and position between station reports, which can help when railway updates are sparse.",
  },
  {
    q: "Is Trayago affiliated with IRCTC or Indian Railways?",
    a: "No. Trayago is an independent travel intelligence platform and is not affiliated with, endorsed by, or operated by IRCTC or Indian Railways. Ticket booking is completed through official booking platforms.",
  },
];

export default function LivePage() {
  // 3. Structured Data Schemas
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Home",
        item: "https://www.trayago.in",
      },
      {
        "@type": "ListItem",
        position: 2,
        name: "Live Train Status",
        item: CANONICAL,
      },
    ],
  };

  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: LIVE_FAQS.map(({ q, a }) => ({
      "@type": "Question",
      name: q,
      acceptedAnswer: {
        "@type": "Answer",
        text: a,
      },
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(faqSchema) }}
      />
      <Suspense fallback={
        <div className="min-h-[50vh] flex flex-col items-center justify-center p-8 space-y-4">
          <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-xs font-semibold text-muted font-mono">Loading Live Train Running Status...</p>
        </div>
      }>
        <LiveClient />
      </Suspense>

      {/* Explanatory SEO content — rendered below the tracker and the existing pre-search copy */}
      <section
        aria-labelledby="live-guide-heading"
        className="w-full px-4 md:px-8 pb-16"
      >
        <div className="max-w-4xl mx-auto w-full border-t border-strong pt-12 space-y-10 text-sm text-secondary leading-relaxed">
          <div className="space-y-3">
            <h2 id="live-guide-heading" className="text-xl font-black text-main">
              How to check live train running status
            </h2>
            <ol className="list-decimal pl-5 space-y-2">
              <li>
                Enter the train number — for example 12951 — in the field at the
                top of this page.
              </li>
              <li>
                Choose the journey date if you are tracking a run that started on
                a previous day.
              </li>
              <li>
                Select <strong>Track Train</strong> to load the current{" "}
                <strong>train running status</strong> for that service.
              </li>
            </ol>
            <p>
              While the page stays open, Trayago refreshes the running
              information automatically so the position and delay stay current
              without a manual reload.
            </p>
          </div>

          <div className="space-y-3">
            <h2 className="text-xl font-black text-main">
              What information can you see?
            </h2>
            <ul className="space-y-2 pl-5 list-disc">
              <li>
                <strong>Current running information</strong> — the station where
                the train was last reported and its progress along the route.
              </li>
              <li>
                <strong>Train delay status</strong> — whether the train is
                running on time or how many minutes late it currently is against
                the scheduled timetable.
              </li>
              <li>
                <strong>Train arrival time and departure time</strong> —
                scheduled timings for each station, with the estimated arrival
                adjusted for the current delay.
              </li>
              <li>
                <strong>Station-wise route</strong> — stations already passed and
                those still upcoming, with halt information where available.
              </li>
              <li>
                <strong>Cancellation and diversion notices</strong> — surfaced
                when the railway data reports them for that run.
              </li>
            </ul>
            <p>
              Running information reflects the most recent report available from
              railway sources, so the displayed position can lag between station
              reports. Estimated timings are projections and can shift while a
              train is en route.
            </p>
          </div>

          <div className="space-y-4">
            <h2 className="text-xl font-black text-main">
              Live train status — frequently asked questions
            </h2>
            <dl className="space-y-5">
              {LIVE_FAQS.map(({ q, a }) => (
                <div key={q} className="space-y-1.5">
                  <dt className="text-sm font-bold text-main">{q}</dt>
                  <dd className="text-sm text-secondary leading-relaxed">
                    {a}
                  </dd>
                </div>
              ))}
            </dl>
          </div>

          <div className="space-y-3 border-t border-strong pt-8">
            <h3 className="text-base font-bold text-main">
              Frequently tracked trains
            </h3>
            <p>
              Open a detailed per-train view with schedule, station timeline and
              map:
            </p>
            <ul className="flex flex-wrap gap-2 pt-1">
              {POPULAR_TRAINS.map(({ number, name }) => (
                <li key={number}>
                  <Link
                    href={`/live/${number}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-card border border-strong text-xs font-semibold text-main hover:border-primary/40 transition-colors"
                  >
                    <span className="font-mono text-primary">{number}</span>
                    <span className="text-secondary font-medium">{name}</span>
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          <div className="space-y-3 border-t border-strong pt-8">
            <h3 className="text-base font-bold text-main">Related tools</h3>
            <p>
              Check a booking with{" "}
              <Link
                href="/pnr"
                className="text-primary font-semibold hover:underline"
              >
                PNR status and confirmation prediction
              </Link>
              , set a destination wake-up alarm with the{" "}
              <Link
                href="/tracker"
                className="text-primary font-semibold hover:underline"
              >
                train tracker
              </Link>
              , explore connecting-train options with the{" "}
              <Link
                href="/split-journey"
                className="text-primary font-semibold hover:underline"
              >
                AI split journey planner
              </Link>
              , find alternative routes using the{" "}
              <Link
                href="/"
                className="text-primary font-semibold hover:underline"
              >
                Trayago train search
              </Link>
              , look for confirmed-seat alternatives with{" "}
              <Link
                href="/ai-waitlist-rescue"
                className="text-primary font-semibold hover:underline"
              >
                AI waitlist rescue
              </Link>
              , track trains on the go with the{" "}
              <Link
                href="/app"
                className="text-primary font-semibold hover:underline"
              >
                Trayago Android app
              </Link>
              , or browse{" "}
              <Link
                href="/news"
                className="text-primary font-semibold hover:underline"
              >
                News &amp; Guides
              </Link>
              .
            </p>
            <p className="text-xs text-muted">
              Trayago is an independent travel intelligence platform and is not
              affiliated with, endorsed by, or operated by IRCTC or Indian
              Railways. Ticket booking is completed through official booking
              platforms.
            </p>
          </div>
        </div>
      </section>
    </>
  );
}
